const scrypt = promisify(scryptCallback);
const ADMIN_EMAIL = 'rodion89@list.ru';
const env = { port: Number(process.env.PORT || 3015), baseUrl: (process.env.PUBLIC_BASE_URL || '').replace(/\/$/, ''), key: Buffer.from(process.env.APP_ENCRYPTION_KEY || '', 'base64'), file: process.env.STATE_PATH || '/var/lib/channel-reposter/app.json', yookassa: { shopId: process.env.YOOKASSA_SHOP_ID || '', secret: process.env.YOOKASSA_SECRET_KEY || '' }, legacy: { tg: process.env.TELEGRAM_BOT_TOKEN || '', tgSecret: process.env.TELEGRAM_WEBHOOK_SECRET || '', source: (process.env.TELEGRAM_SOURCE_CHANNEL_USERNAME || '').replace(/^@/, '').toLowerCase(), max: process.env.MAX_BOT_TOKEN || '', maxSecret: process.env.MAX_WEBHOOK_SECRET || '', target: process.env.MAX_TARGET_CHAT_ID || '' } };
if (env.key.length !== 32) throw new Error('APP_ENCRYPTION_KEY must be a base64-encoded 32-byte key');
if (!env.baseUrl.startsWith('https://')) throw new Error('PUBLIC_BASE_URL must use HTTPS');

let store = { users: [], sessions: [], connections: [], history: [], ledger: [], settings: {}, migrated: false };
let writing = Promise.resolve();
const rid = (bytes = 24) => randomBytes(bytes).toString('base64url');
const stamp = () => new Date().toISOString();
